using SecureProxy.Api.Data;

namespace SecureProxy.Api.Infrastructure;

/// <summary>Body of every error generated by the proxy itself (never by an upstream).</summary>
public sealed record ErrorResponse(string Source, string Code, string Message, string CorrelationId);

/// <summary>
/// A pre-forwarding rejection or a proxy-side failure. Messages are fixed, public-safe texts:
/// they never include hostnames, configuration values, exception details or payload data.
/// </summary>
public sealed class ProxyException(int status, string code, string message, ProxyOutcome outcome = ProxyOutcome.Rejected)
    : Exception(message)
{
    public int Status { get; } = status;
    public string Code { get; } = code;
    public ProxyOutcome Outcome { get; } = outcome;
}

public static class ProxyErrors
{
    /// <summary>Tells the caller who produced the response: "proxy" or "upstream".</summary>
    public const string SourceHeader = "X-Proxy-Source";

    public static Task WriteAsync(HttpContext ctx, int status, string code, string message)
    {
        ctx.Response.StatusCode = status;
        ctx.Response.Headers[SourceHeader] = "proxy";
        return ctx.Response.WriteAsJsonAsync(new ErrorResponse("proxy", code, message, Correlation.Get(ctx)));
    }

    // --- envelope ---
    public static ProxyException UnsupportedMediaType() => new(415, "invalid_content_type", "Content-Type must be application/json.");
    public static ProxyException TooLarge() => new(413, "request_too_large", "The request exceeds the permitted size.");
    public static ProxyException InvalidEnvelope(string message) => new(400, "invalid_request", message);

    // --- policy ---
    public static ProxyException UnknownOperation() => new(404, "operation_not_found", "The requested operation is not configured.");
    public static ProxyException OperationDisabled() => new(403, "operation_disabled", "The requested operation is disabled.");
    public static ProxyException OperationNotPermitted() => new(403, "operation_not_permitted", "The caller is not permitted to execute this operation.");
    public static ProxyException DestinationUnavailable() => new(403, "destination_unavailable", "The destination for this operation is missing or disabled.");
    public static ProxyException DestinationMismatch() => new(400, "destination_mismatch", "urlId does not match the destination configured for this operation.");
    public static ProxyException Misconfigured() => new(500, "operation_misconfigured", "The operation configuration is invalid; the request was not forwarded.", ProxyOutcome.ProxyError);
    public static ProxyException InvalidParameters(string message) => new(400, "invalid_parameters", message);
    public static ProxyException InvalidEncryptedPayload() => new(400, "invalid_encrypted_payload", "The encrypted payload could not be processed.");
    public static ProxyException DestinationBusy() => new(503, "destination_busy", "The destination is at its concurrency limit. Retry later.");

    // --- execution ---
    public static ProxyException UpstreamTimeout() => new(504, "upstream_timeout", "The destination did not respond in time.", ProxyOutcome.UpstreamTimeout);
    public static ProxyException UpstreamUnreachable() => new(502, "upstream_unreachable", "The destination could not be reached.", ProxyOutcome.UpstreamUnreachable);
    public static ProxyException UpstreamResponseTooLarge() => new(502, "upstream_response_too_large", "The destination response exceeds the permitted size.", ProxyOutcome.ProxyError);
    public static ProxyException CallerCancelled() => new(499, "caller_cancelled", "The caller cancelled the request.", ProxyOutcome.CallerCancelled);
    public static ProxyException ConfigurationUnavailable() => new(503, "configuration_unavailable", "Proxy configuration is temporarily unavailable.", ProxyOutcome.ProxyError);
}
